        if self._is_valid_id(doc_id) and doc_id not in self.store and doc_id not in self.archived:
            self.store[doc_id] = body
            return 201
        elif doc_id in self.store:
            return 409
        else:
            return 400

    def read(self, doc_id):
        if self._is_valid_id(doc_id):
            if doc_id in self.store:
                return 200, self.store[doc_id]
            elif doc_id in self.archived:
                return 200, self.archived[doc_id]
            else:
                return 404, None
        else:
            return 400, None

    def put(self, doc_id, body):
        if self._is_valid_id(doc_id):
            if doc_id in self.store:
                self.store[doc_id] = body
                return 200
            elif doc_id in self.archived:
                self.archived.remove(doc_id)
                self.store[doc_id] = body
                return 200
            else:
                return 404
        else:
            return 400

    def archive(self, doc_id):
        if self._is_valid_id(doc_id):
            if doc_id in self.store:
                self.archived.add(doc_id)
                del self.store[doc_id]
                return 200
            elif doc_id in self.archived:
                return 200
            else:
                return 404
        else:
            return 400

    def list(self):
        return sorted(list(self.store.keys()) + list(self.archived))

    def _is_valid_id(self, doc_id):
        if '/' in doc_id or '..' in doc_id:
            return False
        return True
